package org.achievementlabs.mobile;
import android.content.Context;
import org.json.*;
import java.io.*;
import java.util.*;
final class Catalogue {
 final Context context;final JSONObject index;final JSONArray packs;JSONObject synced=new JSONObject();
 Catalogue(JSONObject bundledIndex){context=null;index=bundledIndex;packs=new JSONArray();}
 Catalogue(Context c)throws Exception{context=c;index=new JSONObject(asset("MobileIndex.json"));packs=new JSONObject(asset("achievement-packs.json")).getJSONArray("titles");JSONArray hubs=new JSONObject(asset("achievement-hubs.json")).getJSONArray("titles");for(int i=0;i<hubs.length();i++)packs.put(hubs.getJSONObject(i));}
 String asset(String path)throws Exception{try(InputStream in=context.getAssets().open("catalogue/"+path);ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);return Core.text(b.toByteArray());}}
 boolean matches(JSONObject game,JSONObject definition){JSONArray platforms=definition.optJSONArray("platforms"),devices=game.optJSONArray("devices");if(platforms==null||platforms.length()==0)return true;if(devices==null)return false;for(int i=0;i<platforms.length();i++)for(int x=0;x<devices.length();x++)if(platforms.optString(i).equals(devices.optString(x)))return true;return false;}
 boolean mapped(String title,String id){try{return recipes(title).has(id);}catch(Exception e){return false;}}
 JSONObject recipes(String title)throws Exception{Core.numeric(title);if(synced.has(title))return synced.getJSONObject(title).getJSONObject("recipes").getJSONObject("recipes");JSONObject status=index.optJSONObject(title);if(status==null||!status.isNull("reason"))throw new Exception("No supported event mapping for this edition.");return new JSONObject(asset("Events/"+title+".mapping.json")).getJSONObject("recipes");}
 List<String> payloads(String title,String id,String xuid)throws Exception{return Core.payloads(synced.has(title)?synced.getJSONObject(title).getString("template"):asset("Events/"+title+".json"),recipes(title).getJSONArray(id),title,xuid,System.currentTimeMillis());}
 String pack(JSONObject game,JSONObject row)throws Exception{String title=game.getString("titleId"),id=row.getString("id"),name=row.optString("name");for(int i=0;i<packs.length();i++){JSONObject t=packs.getJSONObject(i);if(!title.equals(t.getString("titleId")))continue;JSONArray devices=game.optJSONArray("devices"),platform=t.optJSONArray("platforms");boolean match=platform==null||platform.length()==0;if(devices!=null&&platform!=null)for(int d=0;d<devices.length();d++)if(platform.toString().contains("\""+devices.getString(d)+"\""))match=true;if(!match)continue;JSONArray groups=t.getJSONArray("packs");for(int g=0;g<groups.length();g++){JSONObject p=groups.getJSONObject(g);JSONArray a=p.getJSONArray("achievements");for(int x=0;x<a.length();x++){JSONObject e=a.getJSONObject(x);if(id.equals(e.getString("id"))&&name.equalsIgnoreCase(e.getString("name")))return p.getString("name");}}}return "Unclassified achievements";}
 int merge(JSONObject feed)throws Exception{if(feed.getInt("schemaVersion")!=1||!feed.getString("archiveSHA256").matches("[a-f0-9]{64}")||java.time.Instant.parse(feed.getString("generatedAt")).isAfter(java.time.Instant.now().plusSeconds(86400)))throw new Exception("Invalid public feed.");JSONObject titles=feed.getJSONObject("titles"),next=new JSONObject(synced.toString());if(titles.length()>5000)throw new Exception("Feed limit exceeded.");int count=0,checks=0;for(Iterator<String> it=titles.keys();it.hasNext();){String id=it.next();if(index.has(id)||next.has(id))continue;Core.numeric(id);JSONObject t=titles.getJSONObject(id),recipes=t.getJSONObject("recipes").getJSONObject("recipes");String template=t.getString("template");if(template.length()>1024*1024||recipes.length()>10000)throw new Exception("Feed limit exceeded.");for(Iterator<String> ids=recipes.keys();ids.hasNext();){if(++checks>50000)throw new Exception("Feed limit exceeded.");String a=Core.numeric(ids.next());Core.payloads(template,recipes.getJSONArray(a),id,"0",System.currentTimeMillis());}if(recipes.length()>0){next.put(id,t);count++;}}synced=next;return count;}
}
